def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    x = np.asarray(history, dtype=float)
    if horizon <= 0:
        return []
    if len(x) == 0:
        return [0.0] * horizon
    x = np.where(np.isfinite(x), x, np.nan)
    fill = float(np.nanmedian(x)) if np.any(np.isfinite(x)) else 0.0
    x = np.where(np.isfinite(x), x, fill)
    p = 24 if 'hour' in frequency.lower() else max(2, min(24, len(x) // 3))
    if len(x) < p + 2:
        return [float(x[-1])] * horizon
    windows = [k for k in (1, 2, 3, 4, 6, 8) if k * p <= len(x)]
    modes = (0, 1, 2)
    best = (float('inf'), 1, 0)
    start = max(p, len(x) - 4 * p)
    for k in windows:
        for mode in modes:
            errors = []
            for origin in range(start, len(x)):
                if origin < k * p:
                    continue
                phase_vals = []
                for j in range(k):
                    phase_vals.append(float(x[origin - p * (j + 1)]))
                pred = float(np.median(phase_vals))
                if mode >= 1:
                    recent = x[max(0, origin - p):origin]
                    prior = x[max(0, origin - 2 * p):max(0, origin - p)]
                    if len(recent) and len(prior):
                        pred += float(np.median(recent) - np.median(prior))
                if mode == 2 and origin >= 2 * p:
                    d = float(x[origin - p] - x[origin - 2 * p])
                    scale = float(np.median(np.abs(np.diff(x[max(0, origin - 2 * p):origin])))) + 1e-9
                    pred += float(np.clip(0.35 * d, -2.5 * scale, 2.5 * scale))
                actual = float(x[origin])
                errors.append(2.0 * abs(pred - actual) / (abs(pred) + abs(actual) + 1e-9))
            score = float(np.mean(errors)) if errors else float('inf')
            if score < best[0]:
                best = (score, k, mode)
    k = best[1]
    mode = best[2]
    out = []
    for step in range(horizon):
        target = len(x) + step
        vals = []
        for j in range(1, k + 1):
            idx = target - j * p
            if idx < len(x):
                vals.append(float(x[idx]))
            elif idx - len(x) < len(out):
                vals.append(float(out[idx - len(x)]))
        pred = float(np.median(vals)) if vals else float(x[-1])
        if mode >= 1 and len(x) >= 2 * p:
            pred += float(np.median(x[-p:]) - np.median(x[-2 * p:-p]))
        if mode == 2 and target - 2 * p >= 0:
            a = float(x[target - p]) if target - p < len(x) else float(out[target - p - len(x)])
            b = float(x[target - 2 * p]) if target - 2 * p < len(x) else float(out[target - 2 * p - len(x)])
            scale = float(np.median(np.abs(np.diff(x[-min(len(x), 2 * p):])))) + 1e-9
            pred += float(np.clip(0.35 * (a - b), -2.5 * scale, 2.5 * scale))
        if not np.isfinite(pred):
            pred = float(x[-1])
        out.append(float(pred))
    return out
